begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select plan(32);
insert into auth.users(id,aud,role,email) values('00000001-0000-4000-8000-000000000031','authenticated','authenticated','som31-owner@example.test'),('00000002-0000-4000-8000-000000000031','authenticated','authenticated','som31-other@example.test');
insert into public.profiles(user_id,display_name) values('00000001-0000-4000-8000-000000000031','Synthetic owner'),('00000002-0000-4000-8000-000000000031','Synthetic other');
insert into public.trainer_workspaces(id,owner_user_id,name) values('00000003-0000-4000-8000-000000000031','00000001-0000-4000-8000-000000000031','SOM31 fixture');
insert into public.client_records(id,workspace_id,user_id,display_name) values('00000004-0000-4000-8000-000000000031','00000003-0000-4000-8000-000000000031','00000002-0000-4000-8000-000000000031','Synthetic client');
insert into public.bookings(id,workspace_id,client_record_id,starts_at,ends_at,status) values('00000005-0000-4000-8000-000000000031','00000003-0000-4000-8000-000000000031','00000004-0000-4000-8000-000000000031',now()+interval '10 days',now()+interval '10 days 1 hour','confirmed');
insert into public.workout_templates(id,workspace_id,name) values('00000006-0000-4000-8000-000000000031','00000003-0000-4000-8000-000000000031','Synthetic plan');
insert into public.booking_programs(id,workspace_id,booking_id,base_template_id,base_template_revision,name) values('00000007-0000-4000-8000-000000000031','00000003-0000-4000-8000-000000000031','00000005-0000-4000-8000-000000000031','00000006-0000-4000-8000-000000000031',1,'Assigned plan');
insert into public.booking_program_exercises(id,workspace_id,booking_program_id,exercise_id,exercise_name_snapshot,measure_snapshot,bodyweight_snapshot,muscle_group_snapshot,equipment_snapshot,instructions_snapshot,source_key_snapshot,position,planned_sets,planned_reps,planned_weight_g,rest_seconds,note)
select '00000008-0000-4000-8000-000000000031',workspace_id,'00000007-0000-4000-8000-000000000031',id,'Immutable assigned name','reps',false,'Assigned muscle','Assigned equipment',array['Assigned instruction'],'assigned-source',0,4,'8–12',25000,75,'Assigned note' from public.exercises where workspace_id='00000003-0000-4000-8000-000000000031' and source_key='e0';
insert into public.template_exercises(workspace_id,template_id,exercise_id,position,planned_sets,planned_reps,planned_weight_g,rest_seconds,note)
select workspace_id,'00000006-0000-4000-8000-000000000031',id,0,4,'8–12',25000,75,'Original template note' from public.exercises where workspace_id='00000003-0000-4000-8000-000000000031' and source_key='e0';
update public.template_exercises set planned_sets=9,planned_reps='1–2',planned_weight_g=99000,rest_seconds=10,note='Changed live template' where template_id='00000006-0000-4000-8000-000000000031';
update public.workout_templates set name='Changed live plan',revision=2 where id='00000006-0000-4000-8000-000000000031';
update public.exercises set archived_at=now(),name='Changed catalog name' where workspace_id='00000003-0000-4000-8000-000000000031' and source_key='e0';
update public.workout_templates set archived_at=now() where id='00000006-0000-4000-8000-000000000031';
select ok(not has_function_privilege('anon','public.prepare_workout_journal(uuid,uuid,uuid)','EXECUTE'),'anonymous cannot prepare');
select ok(not has_table_privilege('authenticated','private.workout_preparation_receipts','SELECT'),'receipts are private');
select ok((select relrowsecurity from pg_class where oid='private.workout_preparation_receipts'::regclass),'private receipts enforce RLS');
select set_config('request.jwt.claim.sub','',true);
set local role authenticated;
select throws_ok($$select public.prepare_workout_journal('00000005-0000-4000-8000-000000000031','00000009-0000-4000-8000-000000000031','00000010-0000-4000-8000-000000000031')$$,'42501','authentication_required','authenticated role without JWT cannot prepare');
select set_config('request.jwt.claim.sub','00000002-0000-4000-8000-000000000031',true);
select throws_ok($$select public.prepare_workout_journal('00000005-0000-4000-8000-000000000031','00000009-0000-4000-8000-000000000031','00000010-0000-4000-8000-000000000031')$$,'P0002','entity_unavailable','linked client cannot prepare');
select set_config('request.jwt.claim.sub','00000001-0000-4000-8000-000000000031',true);
select set_config('test.prepared',public.prepare_workout_journal('00000005-0000-4000-8000-000000000031','00000009-0000-4000-8000-000000000031','00000010-0000-4000-8000-000000000031')::text,true);
select is(current_setting('test.prepared')::jsonb->>'workout_id','00000009-0000-4000-8000-000000000031','requested journal ID preserved');
select is(current_setting('test.prepared')::jsonb->'exercises'->0->>'id','00000008-0000-4000-8000-000000000031','assignment identity maps server exercise');
select is(public.prepare_workout_journal('00000005-0000-4000-8000-000000000031','00000009-0000-4000-8000-000000000031','00000010-0000-4000-8000-000000000031'),current_setting('test.prepared')::jsonb,'exact retry stable');
select throws_ok($$select public.prepare_workout_journal('00000005-0000-4000-8000-000000000031','00000012-0000-4000-8000-000000000031','00000010-0000-4000-8000-000000000031')$$,'22023','request_id_reused','request binds requested UUID');
select is(public.prepare_workout_journal('00000005-0000-4000-8000-000000000031','00000012-0000-4000-8000-000000000031','00000011-0000-4000-8000-000000000031')->>'workout_id','00000009-0000-4000-8000-000000000031','second device adopts existing journal');
select is((select count(*)::integer from public.workout_instances where booking_id='00000005-0000-4000-8000-000000000031'),1,'only one journal');
select is((select exercise_name_snapshot || '|' || muscle_group_snapshot || '|' || equipment_snapshot || '|' || instructions_snapshot[1] || '|' || source_key_snapshot from public.workout_exercises where id='00000008-0000-4000-8000-000000000031'),'Immutable assigned name|Assigned muscle|Assigned equipment|Assigned instruction|assigned-source','catalog changes and archive do not affect assignment');
select is((select planned_sets::text || '|' || planned_reps || '|' || planned_weight_g::text || '|' || rest_seconds::text || '|' || note from public.workout_exercises where id='00000008-0000-4000-8000-000000000031'),'4|8–12|25000|75|Assigned note','all plan fields copied');
select ok(not (current_setting('test.prepared')::jsonb ? 'notes'),'preparation result contains no note payload');
reset role;
insert into public.private_notes(id,workspace_id,workout_instance_id,text,author_user_id,device_id)
values('00000014-0000-4000-8000-000000000031','00000003-0000-4000-8000-000000000031','00000009-0000-4000-8000-000000000031','SOM31 private secret','00000001-0000-4000-8000-000000000031','00000015-0000-4000-8000-000000000031');
set local role authenticated;
select ok(public.prepare_workout_journal('00000005-0000-4000-8000-000000000031','00000009-0000-4000-8000-000000000031',gen_random_uuid())::text not like '%SOM31 private secret%','owner preparation does not return private note text');
select set_config('request.jwt.claim.sub','00000002-0000-4000-8000-000000000031',true);
select is((select count(*)::integer from public.workout_instances where id='00000009-0000-4000-8000-000000000031'),0,'client cannot read draft journal');
select is((select count(*)::integer from public.workout_exercises where workout_instance_id='00000009-0000-4000-8000-000000000031'),0,'client cannot read draft assigned journal rows');
select is((select count(*)::integer from public.private_notes where workout_instance_id='00000009-0000-4000-8000-000000000031'),0,'client cannot read private notes');
select throws_ok($$select public.prepare_workout_journal('00000005-0000-4000-8000-000000000031','00000009-0000-4000-8000-000000000031','00000010-0000-4000-8000-000000000031')$$,'P0002','entity_unavailable','client cannot replay owner preparation receipt');
select set_config('request.jwt.claim.sub','00000001-0000-4000-8000-000000000031',true);
reset role;
update public.workout_exercises set planned_sets=6 where id='00000008-0000-4000-8000-000000000031';
set local role authenticated;
select is((select revision from public.workout_exercises where id='00000008-0000-4000-8000-000000000031'),2,'touch_updated_at increments journal exercise exactly once');
select is(public.prepare_workout_journal('00000005-0000-4000-8000-000000000031','00000009-0000-4000-8000-000000000031','00000010-0000-4000-8000-000000000031'),current_setting('test.prepared')::jsonb,'receipt retry does not reread changed journal');
select is(public.prepare_workout_journal('00000005-0000-4000-8000-000000000031','00000009-0000-4000-8000-000000000031',gen_random_uuid())->'exercises'->0->>'revision','2','new request reads current journal revision');
select is((select planned_sets from public.workout_exercises where id='00000008-0000-4000-8000-000000000031'),6,'retry never overwrites edited journal');
reset role;
update public.workout_instances set finished_at=now() where id='00000009-0000-4000-8000-000000000031';
select set_config('request.jwt.claim.sub','00000002-0000-4000-8000-000000000031',true);
set local role authenticated;
select is((select count(*)::integer from public.workout_instances where id='00000009-0000-4000-8000-000000000031'),1,'linked client sees finished journal');
select is((select count(*)::integer from public.private_notes where workout_instance_id='00000009-0000-4000-8000-000000000031'),0,'private notes remain hidden after finish');
select set_config('request.jwt.claim.sub','00000001-0000-4000-8000-000000000031',true);
reset role;
update public.bookings set status='cancelled_by_trainer' where id='00000005-0000-4000-8000-000000000031';
set local role authenticated;
select is(public.prepare_workout_journal('00000005-0000-4000-8000-000000000031','00000009-0000-4000-8000-000000000031','00000010-0000-4000-8000-000000000031'),current_setting('test.prepared')::jsonb,'cancelled booking still replays successful immutable receipt');
select throws_ok($$select public.prepare_workout_journal('00000005-0000-4000-8000-000000000031','00000009-0000-4000-8000-000000000031',gen_random_uuid())$$,'P0002','entity_unavailable','cancelled booking rejects new request');
reset role;
insert into public.bookings(id,workspace_id,client_record_id,starts_at,ends_at,status)
values('00000013-0000-4000-8000-000000000031','00000003-0000-4000-8000-000000000031','00000004-0000-4000-8000-000000000031',now()+interval '12 days',now()+interval '12 days 1 hour','confirmed');
set local role authenticated;
select throws_ok($$select public.prepare_workout_journal('00000013-0000-4000-8000-000000000031','00000012-0000-4000-8000-000000000031',gen_random_uuid())$$,'P0002','assignment_unavailable','missing assignment is not replaced by live template');
select is((select count(*)::integer from public.workout_instances where booking_id='00000013-0000-4000-8000-000000000031'),0,'missing assignment leaves no partial journal');
select throws_ok($$select public.prepare_workout_journal(null,'00000012-0000-4000-8000-000000000031',gen_random_uuid())$$,'22023','invalid_request','null IDs rejected');
select throws_ok($$select public.prepare_workout_journal('00000013-0000-4000-8000-000000000031',null,gen_random_uuid())$$,'22023','invalid_request','null workout ID rejected');
select throws_ok($$select public.prepare_workout_journal('00000013-0000-4000-8000-000000000031','00000012-0000-4000-8000-000000000031',null)$$,'22023','invalid_request','null request ID rejected');
select * from finish();
rollback;
